"""Generate the TypeScript settings contract and browser catalog fixture from Python."""

import argparse
import json
from pathlib import Path

from purrai.admin_catalog import admin_catalog

ROOT = Path(__file__).resolve().parents[1]


def settings_type(fields):
    lines = [
        "// Generated by scripts/sync_admin_contract.py; edit GroupSettings in schemas.py.",
        "export interface GroupSettings {",
    ]
    types = {"boolean": "boolean", "integer": "number", "number": "number", "string": "string"}
    for name, field in fields.items():
        if "enum" in field:
            value = " | ".join(json.dumps(item, ensure_ascii=False) for item in field["enum"])
        elif field["type"] == "array":
            value = types[field["items"]["type"]] + "[]"
        else:
            value = types[field["type"]]
        lines.append(f"  {name}: {value}")
    return "\n".join(lines + ["}", ""])


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--write", action="store_true")
    mode.add_argument("--check", action="store_true")
    args = parser.parse_args()
    catalog = admin_catalog()
    outputs = {
        ROOT / "frontend/src/groupSettings.ts": settings_type(catalog["settings"]["fields"]),
        ROOT / "frontend/e2e/fixtures/catalog.json": json.dumps(catalog, ensure_ascii=False, indent=2) + "\n",
    }
    stale = []
    for path, content in outputs.items():
        if args.write:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8")
        elif not path.exists() or path.read_text(encoding="utf-8") != content:
            stale.append(str(path.relative_to(ROOT)))
    if stale:
        parser.exit(1, "配置契约需要同步：" + "、".join(stale) + "；运行本脚本 --write。\n")
    print("管理配置契约已同步" if args.write else "管理配置契约一致")


if __name__ == "__main__":
    main()
